try {
  await processPayment(order);
} catch (err) {
  if (err instanceof NetworkError) {
    await retryQueue.push(order);
    return;
  }
  if (err instanceof ValidationError) {
    respond(400, err.message);
    return;
  }
  throw err; // unknown — propagate
}

let lock;
try {
  lock = await acquireLock("job-42");
  await runJob();
} finally {
  if (lock) await lock.release();
}
// Same idea as C# using — release even if runJob throws

function trap() {
  try {
    return 1;
  } finally {
    return 2;
  }
}
console.log(trap()); // 2 — finally overrides

function safe() {
  try {
    return 1;
  } finally {
    cleanup(); // ok — no return in finally
  }
}
